diff --git a/js/packages/host-companion/src/server.ts b/js/packages/host-companion/src/server.ts
new file mode 100644
index 00000000..e22fd118
--- /dev/null
+++ b/js/packages/host-companion/src/server.ts
@@ -0,0 +1,262 @@
+import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
+import type { AddressInfo } from "node:net";
+import { networkInterfaces } from "node:os";
+import {
+  HOST_CONTROL_PROTOCOL_VERSION,
+  HOST_CONTROL_WIRE_ERRORS,
+  isRecord,
+  isWireErrorCode,
+  type HostControlWireErrorCode,
+  type ImplementedHostPlugin,
+} from "@vitadeck/sdk/host-control";
+import { implementCorePlugin } from "./core";
+import { createEventLog, EVENT_WAIT_MS } from "./events";
+
+export const MAX_REQUEST_BYTES = 64 * 1024;
+
+export type HostCompanionOptions = {
+  port: number;
+  host?: string;
+  name: string;
+  platform?: string;
+  /** Loaded after `core`, which is always served. */
+  plugins?: readonly ImplementedHostPlugin[];
+  /** Linked Vita IPs, read per request so a `link` from another process applies at once. */
+  vitas?: () => Promise<readonly string[]>;
+  remoteAddress?: (request: IncomingMessage) => string | undefined;
+  log?: (line: string) => void;
+  /** How long `core.events` waits for an event; shortened in tests. */
+  eventWaitMs?: number;
+};
+
+export type RunningHostCompanion = {
+  port: number;
+  /** Replaces every plugin but `core`, stopping the old ones and starting the new, or throws and keeps them. */
+  setPlugins: (plugins: readonly ImplementedHostPlugin[]) => void;
+  close: () => Promise<void>;
+};
+
+type Reply = { status: number; label: string; outcome: string; body: object };
+
+function fail(label: string, code: HostControlWireErrorCode, message: string): Reply {
+  return { status: HOST_CONTROL_WIRE_ERRORS[code], label, outcome: code, body: { ok: false, code, message } };
+}
+
+export function normalizeAddress(address: string): string {
+  return address.startsWith("::ffff:") ? address.slice("::ffff:".length) : address;
+}
+
+function isLoopback(address: string): boolean {
+  return address === "::1" || address.startsWith("127.");
+}
+
+function ownAddresses(): string[] {
+  return Object.values(networkInterfaces()).flatMap((list) => list?.map((info) => info.address) ?? []);
+}
+
+function readBody(request: IncomingMessage): Promise<Buffer | undefined> {
+  return new Promise((resolve, reject) => {
+    const chunks: Buffer[] = [];
+    let size = 0;
+    // Drains past the limit so the 413 reaches a client that is still sending.
+    request.on("data", (chunk: Buffer) => {
+      size += chunk.length;
+      if (size <= MAX_REQUEST_BYTES) chunks.push(chunk);
+    });
+    request.on("end", () => {
+      resolve(size <= MAX_REQUEST_BYTES ? Buffer.concat(chunks) : undefined);
+    });
+    request.on("error", reject);
+  });
+}
+
+/** Matched by shape, since a Host Plugin Package throws its own bundled copy of `HostCommandError`. */
+function wireErrorCode(error: unknown): HostControlWireErrorCode | undefined {
+  return error instanceof Error && error.name === "HostCommandError" && "code" in error && isWireErrorCode(error.code)
+    ? error.code
+    : undefined;
+}
+
+function parseJson(text: string): unknown {
+  try {
+    return JSON.parse(text);
+  } catch {
+    return undefined;
+  }
+}
+
+export async function startHostCompanion(options: HostCompanionOptions): Promise<RunningHostCompanion> {
+  const {
+    name,
+    platform = process.platform,
+    vitas = () => Promise.resolve([]),
+    remoteAddress = (request: IncomingMessage) => request.socket.remoteAddress,
+    log = (line) => {
+      console.log(line);
+    },
+  } = options;
+
+  const events = createEventLog(options.eventWaitMs ?? EVENT_WAIT_MS);
+  let plugins = new Map<string, ImplementedHostPlugin>();
+  const core = implementCorePlugin(name, platform, () => [...plugins.values()], events);
+
+  // Each plugin's lifecycle runs while it is loaded; an emit after its stop is dropped.
+  function startPlugins(loaded: readonly ImplementedHostPlugin[]): () => void {
+    let running = true;
+    const stops = loaded.flatMap((plugin) => {
+      try {
+        const stop = plugin.start?.((event, data) => {
+          if (running) events.emit(plugin.id, event, data);
+        });
+        return stop ? [stop] : [];
+      } catch (error) {
+        log(`Plugin ${plugin.id} failed to start: ${error instanceof Error ? error.message : String(error)}`);
+        return [];
+      }
+    });
+    return () => {
+      if (!running) return;
+      running = false;
+      for (const stop of stops) {
+        try {
+          stop();
+        } catch (error) {
+          log(`A plugin failed to stop: ${error instanceof Error ? error.message : String(error)}`);
+        }
+      }
+    };
+  }
+
+  function byId(next: readonly ImplementedHostPlugin[]): Map<string, ImplementedHostPlugin> {
+    const map = new Map([[core.id, core]]);
+    for (const plugin of next) {
+      if (map.has(plugin.id)) throw new Error(`Two loaded plugins share the id ${plugin.id}.`);
+      map.set(plugin.id, plugin);
+    }
+    return map;
+  }
+
+  plugins = byId(options.plugins ?? []);
+  let stopRunning = startPlugins([]);
+
+  function setPlugins(next: readonly ImplementedHostPlugin[]): void {
+    const loaded = byId(next);
+    stopRunning();
+    plugins = loaded;
+    stopRunning = startPlugins(next);
+  }
+
+  async function isAllowed(peer: string): Promise<boolean> {
+    const linked = await vitas();
+    return linked.length === 0 || isLoopback(peer) || linked.includes(peer) || ownAddresses().includes(peer);
+  }
+
+  async function reply(request: IncomingMessage, peer: string): Promise<Reply> {
+    const route = `${request.method ?? "?"} ${request.url ?? "?"}`;
+    if (!(await isAllowed(peer))) {
+      // Discards the body unbuffered, so a peer that is not linked costs no memory.
+      request.resume();
+      return fail(route, "forbidden", "This Host Companion only answers the VitaDeck it is linked with.");
+    }
+    const body = await readBody(request);
+    // Every status comes from HOST_CONTROL_WIRE_ERRORS, so an unknown route is an unknown command.
+    if (new URL(request.url ?? "/", "http://companion").pathname !== "/command") {
+      return fail(route, "unknown_command", "This Host Companion serves only POST /command.");
+    }
+    if (request.method !== "POST") return fail(route, "malformed_request", "Send commands with POST /command.");
+    const contentType = request.headers["content-type"]?.split(";")[0]?.trim().toLowerCase();
+    if (contentType !== "application/json") {
+      return fail(route, "malformed_request", "Send commands with Content-Type: application/json.");
+    }
+    if (body === undefined) {
+      return fail(route, "payload_too_large", `A command request may be at most ${MAX_REQUEST_BYTES} bytes.`);
+    }
+
+    const envelope = parseJson(body.toString("utf8"));
+    if (!isRecord(envelope) || typeof envelope.protocolVersion !== "number") {
+      return fail(route, "malformed_request", "The request body is not a Host Control command.");
+    }
+    if (envelope.protocolVersion !== HOST_CONTROL_PROTOCOL_VERSION) {
+      return fail(
+        route,
+        "unsupported_protocol_version",
+        `This Host Companion speaks Host Control protocol version ${HOST_CONTROL_PROTOCOL_VERSION}.`,
+      );
+    }
+    if (typeof envelope.plugin !== "string" || typeof envelope.command !== "string") {
+      return fail(route, "malformed_request", "The request body is not a Host Control command.");
+    }
+
+    const label = `${envelope.plugin}.${envelope.command}`;
+    const plugin = plugins.get(envelope.plugin);
+    if (!plugin) return fail(label, "unknown_plugin", `This Host Companion has no plugin ${envelope.plugin}.`);
+    const command = plugin.commands.get(envelope.command);
+    if (!command) return fail(label, "unknown_command", `Plugin ${plugin.id} has no command ${envelope.command}.`);
+    if (!command.isPayload(envelope.payload)) return fail(label, "invalid_payload", `Invalid payload for ${label}.`);
+
+    try {
+      const result = await command.run(envelope.payload);
+      return { status: 200, label, outcome: "ok", body: { ...result, ok: true } };
+    } catch (error) {
+      const message = error instanceof Error ? error.message : String(error);
+      return fail(label, wireErrorCode(error) ?? "command_failed", message);
+    }
+  }
+
+  async function answer(request: IncomingMessage, response: ServerResponse): Promise<void> {
+    const started = performance.now();
+    const peer = normalizeAddress(remoteAddress(request) ?? "unknown");
+    let result: Reply;
+    try {
+      result = await reply(request, peer);
+    } catch (error) {
+      result = fail("?", "command_failed", String(error));
+    }
+    const text = JSON.stringify(result.body);
+    response.writeHead(result.status, {
+      "Content-Type": "application/json",
+      "Content-Length": Buffer.byteLength(text),
+      Connection: "close",
+    });
+    response.end(text);
+    const ms = Math.round(performance.now() - started);
+    log(`${new Date().toISOString()} ${peer} ${result.label} ${result.outcome} ${ms}ms`);
+  }
+
+  const server = createServer((request, response) => {
+    void answer(request, response);
+  });
+
+  await new Promise<void>((resolve, reject) => {
+    server.once("error", (error: NodeJS.ErrnoException) => {
+      reject(
+        error.code === "EADDRINUSE"
+          ? new Error(`Port ${options.port} is already in use. Stop the other program or choose another --port.`)
+          : error,
+      );
+    });
+    server.listen(options.port, options.host ?? "0.0.0.0", () => {
+      resolve();
+    });
+  });
+  // Lifecycles start once the port is bound, so a busy port leaves no plugin timer keeping the process alive.
+  stopRunning = startPlugins(options.plugins ?? []);
+
+  return {
+    port: (server.address() as AddressInfo).port,
+    setPlugins,
+    close: () =>
+      new Promise((resolve, reject) => {
+        events.close();
+        stopRunning();
+        if (!server.listening) {
+          resolve();
+          return;
+        }
+        server.close((error) => {
+          if (error) reject(error);
+          else resolve();
+        });
+      }),
+  };
+}

diff --git a/js/packages/host-companion/test/server.test.ts b/js/packages/host-companion/test/server.test.ts
new file mode 100644
index 00000000..0d9a479f
--- /dev/null
+++ b/js/packages/host-companion/test/server.test.ts
@@ -0,0 +1,432 @@
+import assert from "node:assert/strict";
+import { mkdir, readFile, readdir, writeFile } from "node:fs/promises";
+import { networkInterfaces } from "node:os";
+import path from "node:path";
+import test from "node:test";
+import { setTimeout as sleep } from "node:timers/promises";
+import { fileURLToPath } from "node:url";
+import {
+  command,
+  corePlugin,
+  createHostClient,
+  defineHostPlugin,
+  event,
+  implementHostPlugin,
+  isAbsent,
+  systemStatsPlugin,
+} from "@vitadeck/sdk/host-control";
+import { strToU8, zipSync } from "fflate";
+import { extractHostPluginArchive, loadHostPluginPackage } from "../src/plugin";
+import { MAX_REQUEST_BYTES, startHostCompanion, type HostCompanionOptions } from "../src/server";
+import { systemStats } from "../src/system-stats";
+import { greeterPlugin } from "./fixtures/greeter-plugin";
+import { buildGreeterPackage, tempDir, writePackage } from "./fixtures/plugin-package";
+
+const alertsPlugin = defineHostPlugin(
+  "alerts",
+  { ping: command<undefined, object>(isAbsent) },
+  { fired: event<{ level: number }>() },
+);
+
+/** An `alerts` implementation whose emit the test drives, and a record of its lifecycle. */
+function alertsWithEmit() {
+  const lifecycle = { emit: (_level: number) => {}, stopped: false };
+  const plugin = implementHostPlugin(
+    alertsPlugin,
+    { ping: () => ({}) },
+    {
+      start(emit) {
+        lifecycle.emit = (level) => {
+          emit("fired", { level });
+        };
+        return () => {
+          lifecycle.stopped = true;
+        };
+      },
+    },
+  );
+  return { plugin, lifecycle };
+}
+
+type Fixture = { request: unknown; status: number; response: unknown };
+
+const fixturesDir = fileURLToPath(new URL("../../../../tests/fixtures/host-control/", import.meta.url));
+
+async function companion(t: test.TestContext, options: Partial<HostCompanionOptions> = {}) {
+  return `http://127.0.0.1:${(await runningCompanion(t, options)).port}/`;
+}
+
+async function runningCompanion(t: test.TestContext, options: Partial<HostCompanionOptions> = {}) {
+  const running = await startHostCompanion({
+    port: 0,
+    host: "127.0.0.1",
+    name: "Fixture Host",
+    platform: "darwin",
+    log: () => {},
+    ...options,
+  });
+  t.after(() => running.close());
+  return running;
+}
+
+async function post(url: string, body: string, headers?: Record<string, string>) {
+  const response = await fetch(`${url}command`, {
+    method: "POST",
+    headers: { "Content-Type": "application/json", ...headers },
+    body,
+  });
+  return { status: response.status, headers: response.headers, body: await response.json() };
+}
+
+const commandFixtures = (await readdir(fixturesDir)).filter(
+  (name) => name.endsWith(".json") && !name.startsWith("link-"),
+);
+
+for (const name of commandFixtures) {
+  void test(`replays fixture ${name}`, async (t) => {
+    const fx = JSON.parse(await readFile(`${fixturesDir}${name}`, "utf8")) as Fixture;
+    const url = await companion(t);
+    const response = await post(url, JSON.stringify(fx.request));
+    assert.equal(response.status, fx.status);
+    assert.deepEqual(response.body, fx.response);
+    assert.equal(response.headers.get("content-type"), "application/json");
+    assert.equal(response.headers.get("connection"), "close");
+  });
+}
+
+void test("rejects a body over 64 KiB with payload_too_large", async (t) => {
+  const url = await companion(t);
+  const text = "x".repeat(MAX_REQUEST_BYTES);
+  const response = await post(
+    url,
+    JSON.stringify({ protocolVersion: 1, plugin: "core", command: "echo", payload: { text } }),
+  );
+  assert.equal(response.status, 413);
+  assert.deepEqual(response.body, {
+    ok: false,
+    code: "payload_too_large",
+    message: "A command request may be at most 65536 bytes.",
+  });
+});
+
+void test("rejects a wrong method, content type, route, and malformed JSON", async (t) => {
+  const url = await companion(t);
+
+  const get = await fetch(`${url}command`);
+  assert.equal(get.status, 400);
+  assert.deepEqual(await get.json(), {
+    ok: false,
+    code: "malformed_request",
+    message: "Send commands with POST /command.",
+  });
+
+  const text = await post(url, "{}", { "Content-Type": "text/plain" });
+  assert.equal(text.status, 400);
+  assert.deepEqual(text.body, {
+    ok: false,
+    code: "malformed_request",
+    message: "Send commands with Content-Type: application/json.",
+  });
+
+  const route = await fetch(`${url}other`, { method: "POST" });
+  assert.equal(route.status, 404);
+  assert.deepEqual(await route.json(), {
+    ok: false,
+    code: "unknown_command",
+    message: "This Host Companion serves only POST /command.",
+  });
+
+  const malformed = await post(url, "{not json", { "Content-Type": "application/json; charset=utf-8" });
+  assert.equal(malformed.status, 400);
+  assert.deepEqual(malformed.body, {
+    ok: false,
+    code: "malformed_request",
+    message: "The request body is not a Host Control command.",
+  });
+});
+
+void test("serves the SDK client for core and system stats", async (t) => {
+  const url = await companion(t, { plugins: [systemStats] });
+
+  const core = createHostClient(corePlugin, { url });
+  assert.deepEqual(await core.echo({ text: "hello" }), { ok: true, text: "hello" });
+  const capabilities = await core.capabilities();
+  assert.ok(capabilities.ok);
+  assert.deepEqual(capabilities.plugins, [
+    { id: "core", commands: ["capabilities", "echo", "events", "notify"] },
+    { id: "systemStats", commands: ["read"] },
+  ]);
+
+  const client = createHostClient(systemStatsPlugin, { url });
+  // The first read samples the CPU twice; later reads measure since the previous one.
+  for (const stats of [await client.read(), await client.read()]) {
+    assert.ok(stats.ok);
+    assert.ok(stats.cpuPercent >= 0 && stats.cpuPercent <= 100);
+    assert.equal(stats.cpuPercent, Math.round(stats.cpuPercent * 10) / 10);
+    assert.ok(stats.memoryUsedPercent > 0 && stats.memoryUsedPercent <= 100);
+    assert.ok(Number.isInteger(stats.memoryTotalBytes) && stats.memoryTotalBytes > 0);
+    assert.ok(Number.isInteger(stats.uptimeSeconds) && stats.uptimeSeconds > 0);
+  }
+});
+
+void test("loads a bundled Host Plugin Package and maps its throws, including its own HostCommandError", async (t) => {
+  const plugin = await loadHostPluginPackage(await buildGreeterPackage(t));
+  const url = await companion(t, { plugins: [plugin] });
+  const greeter = createHostClient(greeterPlugin, { url });
+
+  assert.deepEqual(await greeter.greet({ name: "Máté" }), { ok: true, greeting: "Hello, Máté!" });
+  assert.deepEqual(await greeter.crash(), { ok: false, code: "command_failed", message: "The greeter fell over." });
+  assert.deepEqual(await greeter.launch(), {
+    ok: false,
+    code: "unsupported_platform",
+    message: "Launching is not supported on this computer.",
+  });
+});
+
+void test("a package's entry reads the package's other files through import.meta.url", async (t) => {
+  const packageDir = await writePackage(
+    await tempDir(t),
+    "files",
+    `import { readFileSync } from "node:fs";
+const read = () => ({ text: readFileSync(new URL("./files/greeting.txt", import.meta.url), "utf8") });
+export default { id: "files", commands: new Map([["read", { isPayload: () => true, run: read }]]) };
+`,
+  );
+  await mkdir(path.join(packageDir, "files"));
+  await writeFile(path.join(packageDir, "files", "greeting.txt"), "Hello from a file");
+  const plugin = await loadHostPluginPackage(packageDir);
+  assert.deepEqual(await plugin.commands.get("read")?.run(null), { text: "Hello from a file" });
+});
+
+void test("rejects a folder that is not a Host Plugin Package", async (t) => {
+  const dir = await tempDir(t);
+  const plain = (name: string, id: string) =>
+    writePackage(dir, name, `export default { id: ${JSON.stringify(id)}, commands: new Map() };\n`);
+
+  await assert.rejects(loadHostPluginPackage(path.join(dir, "missing.vdplugin")), /has no readable manifest\.json/u);
+  await assert.rejects(
+    loadHostPluginPackage(await writePackage(dir, "number", "export default 1;\n")),
+    /does not default-export implementHostPlugin/u,
+  );
+  await assert.rejects(
+    loadHostPluginPackage(await writePackage(dir, "broken", "export default {\n")),
+    /broken\.vdplugin failed to load/u,
+  );
+  await assert.rejects(loadHostPluginPackage(await plain("escape", "../x")), /has plugin id "\.\.\/x"/u);
+  await assert.rejects(
+    loadHostPluginPackage(await writePackage(dir, "future", "", { schemaVersion: 2, entry: "companion.mjs" })),
+    /is not a Host Plugin Package manifest/u,
+  );
+  await assert.rejects(
+    loadHostPluginPackage(await writePackage(dir, "outside", "", { schemaVersion: 1, entry: "../x.mjs" })),
+    /names an entry outside the package/u,
+  );
+  assert.equal((await loadHostPluginPackage(await plain("digits", "2048"))).id, "2048");
+});
+
+void test("extracting an archive refuses unsafe paths and anything but one .vdplugin folder", async (t) => {
+  const dir = await tempDir(t);
+  const archive = async (name: string, files: Record<string, string>) => {
+    const file = path.join(dir, name);
+    const entries = Object.fromEntries(Object.entries(files).map(([key, text]) => [key, strToU8(text)]));
+    await writeFile(file, zipSync(entries));
+    return file;
+  };
+  await assert.rejects(
+    extractHostPluginArchive(await archive("two.vdplugin.zip", { "a.vdplugin/m": "", "b.vdplugin/m": "" }), dir),
+    /exactly one top-level \.vdplugin folder/u,
+  );
+  await assert.rejects(
+    extractHostPluginArchive(await archive("slip.vdplugin.zip", { "a.vdplugin/../../evil": "" }), dir),
+    /holds an unsafe path/u,
+  );
+  const mac = await archive("mac.vdplugin.zip", { "a.vdplugin/manifest.json": "{}", "__MACOSX/a.vdplugin/._x": "" });
+  assert.equal(await extractHostPluginArchive(mac, path.join(dir, "out")), path.join(dir, "out", "a.vdplugin"));
+});
+
+void test("setPlugins swaps the plugins, keeping core, and keeps them when ids clash", async (t) => {
+  const running = await runningCompanion(t);
+  const core = createHostClient(corePlugin, { url: `http://127.0.0.1:${running.port}/` });
+  const ids = async () => {
+    const capabilities = await core.capabilities();
+    assert.ok(capabilities.ok);
+    return capabilities.plugins.map((plugin) => plugin.id);
+  };
+
+  assert.deepEqual(await ids(), ["core"]);
+  running.setPlugins([systemStats]);
+  assert.deepEqual(await ids(), ["core", "systemStats"]);
+  assert.throws(() => {
+    running.setPlugins([systemStats, systemStats]);
+  }, /share the id systemStats/u);
+  assert.deepEqual(await ids(), ["core", "systemStats"]);
+});
+
+void test("refuses two plugins with the same id", async () => {
+  const duplicate = implementHostPlugin(defineHostPlugin("core", { ping: command<undefined, object>(isAbsent) }), {
+    ping: () => ({}),
+  });
+  await assert.rejects(
+    startHostCompanion({ port: 0, host: "127.0.0.1", name: "x", plugins: [duplicate], log: () => {} }),
+    /share the id core/u,
+  );
+});
+
+void test("a busy port fails instead of moving", async (t) => {
+  const url = await companion(t);
+  const port = Number(new URL(url).port);
+  await assert.rejects(startHostCompanion({ port, host: "127.0.0.1", name: "x", log: () => {} }), /already in use/u);
+});
+
+void test("once linked, answers only linked Vitas, loopback and own addresses", async (t) => {
+  const lines: string[] = [];
+  const url = await companion(t, {
+    vitas: () => Promise.resolve(["192.168.1.177"]),
+    remoteAddress: (request) => String(request.headers["x-peer"]),
+    log: (line) => {
+      lines.push(line);
+    },
+  });
+  const echo = JSON.stringify({ protocolVersion: 1, plugin: "core", command: "echo", payload: { text: "secret" } });
+  const as = (peer: string) => post(url, echo, { "X-Peer": peer });
+
+  const own = Object.values(networkInterfaces()).flatMap((list) => list?.map((info) => info.address) ?? []);
+  const allowed = ["::ffff:192.168.1.177", "192.168.1.177", "127.0.0.1", "::1", ...own];
+  const statuses = await Promise.all(allowed.map(async (peer) => (await as(peer)).status));
+  assert.deepEqual(new Set(statuses), new Set([200]));
+
+  const forbidden = await as("::ffff:192.168.1.50");
+  assert.equal(forbidden.status, 403);
+  assert.deepEqual(forbidden.body, {
+    ok: false,
+    code: "forbidden",
+    message: "This Host Companion only answers the VitaDeck it is linked with.",
+  });
+
+  assert.ok(lines.some((line) => / 192\.168\.1\.177 core\.echo ok \d+ms$/u.test(line)));
+  assert.ok(lines.some((line) => / 192\.168\.1\.50 POST \/command forbidden \d+ms$/u.test(line)));
+  assert.ok(lines.every((line) => !line.includes("secret")));
+});
+
+void test("before any link, answers every peer", async (t) => {
